  idLadder(j) { const L = this.idLegal(j), out = []; for (let e = Math.floor(Math.log10(L)) + 1; e >= 0 && out.length < 5; e--) { [7.5, 5, 2.5, 2, 1].forEach(m => { const v = m * Math.pow(10, e); if (v < L && v >= 1 && out.length < 5 && out.indexOf(v) < 0) out.push(v); }); } return out.sort((a, b) => b - a).slice(0, 5); }
